import sys
from collections import defaultdict

MOD = 1000000007

def matrix_mult(A, B):
    n = len(A)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % MOD
    return result

def matrix_pow(matrix, power):
    result = [[1 if i == j else 0 for j in range(len(matrix))] for i in range(len(matrix))]
    base = [row[:] for row in matrix]
    while power:
        if power & 1:
            result = matrix_mult(result, base)
        base = matrix_mult(base, base)
        power //= 2
    return result

def count_trees(n, edges):
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    def dfs(node, parent):
        subtree_sizes = [1]
        for neighbor in adj[node]:
            if neighbor != parent:
                subtree_sizes.extend(dfs(neighbor, node))
        return subtree_sizes

    sizes = dfs(1, -1)
    total_trees = pow(n, n - 2, MOD)
    result = [0] * n

    for k in range(n):
        dp = [[0] * (k + 1) for _ in range(n + 1)]
        dp[0][0] = 1

        for size in sizes:
            new_dp = [[0] * (k + 1) for _ in range(size + 1)]
            for i in range(size + 1):
                for j in range(k + 1):
                    new_dp[i][j] = (new_dp[i][j] + dp[i][j] * pow(n - size, size - i, MOD)) % MOD
                    if i > 0 and j < k:
                        new_dp[i][j + 1] = (new_dp[i][j + 1] + dp[i - 1][j] * i * pow(n - size, size - i, MOD)) % MOD
            dp = new_dp

        result[k] = dp[-1][-1]

    return [(total_trees - x) % MOD for x in result[:-1]] + [result[-1]]

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    edges = [(int(input[2 * i + 1]), int(input[2 * i + 2])) for i in range(n - 1)]
    result = count_trees(n, edges)
    print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
